      }
      interruptTurnId = id;
      interruptPromise ??= this.client
        .request("turn/interrupt", { threadId, turnId: id })
        .then(
          () => {
            releaseOnce();
          },
          (error: unknown) => {
            this.client.recycleUncertainSession(
              new Error(`Turn interrupt failed; recycling uncertain app-server session`, {
                cause: error,
              }),
            );
            releaseOnce();
            throw error;
          },
        );
