    if (process.argv.includes("reject-interrupt")) {
      send({ id, error: { code: -32000, message: "interrupt rejected" } });
      return;
    }
    if (process.argv.includes("never-interrupt-ack")) return;
    setTimeout(() => {
      active -= 1;
      reportActive();
      send({ id, result: {} });
    }, 40);
  } else {
    send({ id, result: {} });
  }
